const dgram = require('dgram');
const qname = 'connectivity.audit.test';
const id = Math.floor(Math.random()*65536);
const parts = [];
const header = Buffer.alloc(12);
header.writeUInt16BE(id,0); header.writeUInt16BE(0x0100,2); header.writeUInt16BE(1,4);
parts.push(header);
for (const label of qname.split('.')) parts.push(Buffer.from([label.length]), Buffer.from(label));
const tail = Buffer.alloc(5); tail[0]=0; tail.writeUInt16BE(1,1); tail.writeUInt16BE(1,3); parts.push(tail);
const msg = Buffer.concat(parts);
const sock = dgram.createSocket('udp4');
const timer = setTimeout(()=>{ console.log('timeout waiting for response from 127.0.0.1:47302'); sock.close(); }, 2000);
sock.on('message', (data, rinfo)=>{
  clearTimeout(timer);
  const rcode = data.length >= 4 ? (data[3] & 0x0f) : 'n/a';
  const answers = data.length >= 8 ? data.readUInt16BE(6) : 'n/a';
  console.log(`received ${data.length} bytes from ${rinfo.address}:${rinfo.port}; rcode=${rcode}; answers=${answers}`);
  sock.close();
});
sock.on('error', (err)=>{ clearTimeout(timer); console.log(`error: ${err.message}`); sock.close(); });
sock.send(msg, 47302, '127.0.0.1');
